/**
 * FolderItem Component
 *
 * Renders a folder in the node pool.
 * Supports nested folders and drag and drop.
 */

import { memo, useState, useCallback } from 'react'
import {
  Folder,
  FolderOpen,
  ChevronRight,
  ChevronDown,
} from 'lucide-react'
import { clsx } from 'clsx'
import type { FolderItemProps } from '../types/node-pool'
import { NodeCardItem } from './NodeCardItem'

/**
 * Folder item component with drag and drop support
 */
export const FolderItem = memo(function FolderItem({
  folder,
  level = 0,
  cards,
  children,
  isDragOver,
  dragOverPosition,
  onToggle,
  onContextMenu,
  onCardContextMenu,
  previewCardId,
  onTogglePreview,
  onDrop,
  onDragOver,
  onDragLeave,
}: FolderItemProps) {
  const [isLocalDragOver, setIsLocalDragOver] = useState(false)

  const handleToggle = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    onToggle?.(folder.id)
  }

  const handleStartEdit = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    // TODO: Implement edit mode
  }

  const handleDelete = (e: React.MouseEvent) => {
    e.preventDefault()
    e.stopPropagation()
    // TODO: Implement delete
  }

  const handleFolderDragOver = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsLocalDragOver(true)
    onDragOver?.(e, folder)
  }, [folder, onDragOver])

  const handleFolderDragLeave = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsLocalDragOver(false)
    onDragLeave?.(e, folder)
  }, [folder, onDragLeave])

  const handleFolderDrop = useCallback((e: React.DragEvent) => {
    e.preventDefault()
    e.stopPropagation()
    setIsLocalDragOver(false)
    onDrop?.(e, folder)
  }, [folder, onDrop])

  const isCollapsed = folder.collapsed

  return (
    <>
      {/* Folder header */}
      <div
        style={{ paddingLeft: `${level * 16 + 8}px` }}
        className={clsx(
          'flex items-center gap-1 px-2 py-1.5 rounded-lg cursor-pointer hover:bg-gray-100 dark:hover:bg-gray-700 transition-all duration-200',
          isLocalDragOver && 'bg-blue-100 dark:bg-blue-900/40 ring-2 ring-blue-500 ring-opacity-50 scale-[1.02] shadow-sm'
        )}
        onClick={handleToggle}
        onContextMenu={(e) => onContextMenu?.(e, folder)}
        onDragOver={handleFolderDragOver}
        onDragLeave={handleFolderDragLeave}
        onDrop={handleFolderDrop}
      >
        {/* Expand/collapse indicator */}
        {children.length > 0 || cards.length > 0 ? (
          isCollapsed ? (
            <ChevronRight className="w-3.5 h-3.5 text-gray-500" />
          ) : (
            <ChevronDown className="w-3.5 h-3.5 text-gray-500" />
          )
        ) : null}

        {/* Folder icon */}
        {isCollapsed ? (
          <Folder className={clsx('w-4 h-4', isLocalDragOver ? 'text-blue-500' : 'text-gray-400 dark:text-gray-500')} />
        ) : (
          <FolderOpen className={clsx('w-4 h-4', isLocalDragOver ? 'text-blue-600' : 'text-blue-500')} />
        )}

        {/* Folder name */}
        <span className={clsx('text-sm font-medium flex-1 truncate', isLocalDragOver ? 'text-blue-700 dark:text-blue-300' : 'text-gray-700 dark:text-gray-300')}>
          {folder.name}
        </span>

        {/* Card count */}
        <span className={clsx('text-xs', isLocalDragOver ? 'text-blue-600 dark:text-blue-400' : 'text-gray-500 dark:text-gray-400')}>
          {cards.length}
        </span>
      </div>

      {/* Folder contents (when expanded) */}
      {!isCollapsed && (
        <div
          className={clsx(
            'ml-4 pl-2 border-l border-gray-200 dark:border-gray-700 my-1 space-y-1 rounded-lg transition-all duration-200',
            isLocalDragOver && 'bg-blue-50 dark:bg-blue-900/30 border-blue-300 dark:border-blue-700 border-l-2'
          )}
          onDragOver={handleFolderDragOver}
          onDragLeave={handleFolderDragLeave}
          onDrop={handleFolderDrop}
        >
          {/* Cards in this folder */}
          {cards.map((card) => (
            <div key={card.id} className="py-0.5">
              <NodeCardItem
                card={card}
                isDragging={false}
                isDragOver={false}
                dragOverPosition={null}
                onUse={(c) => {
                  // TODO: Implement use card
                }}
                onRemove={(id) => {
                  // TODO: Implement remove
                }}
                onSaveName={(id, name) => {
                  // TODO: Implement save name
                }}
                onContextMenu={onCardContextMenu}
                showPreview={previewCardId === card.id}
                onTogglePreview={onTogglePreview}
              />
            </div>
          ))}

          {/* Nested folders */}
          {children.map((child) => (
            <FolderItem
              key={child.id}
              folder={child}
              level={level + 1}
              cards={[]} // Cards will be passed from parent
              children={child.children || []}
              isDragOver={false}
              dragOverPosition={null}
              onToggle={onToggle}
              onContextMenu={onContextMenu}
              onCardContextMenu={onCardContextMenu}
              previewCardId={previewCardId}
              onTogglePreview={onTogglePreview}
              onDrop={onDrop}
              onDragOver={onDragOver}
              onDragLeave={onDragLeave}
            />
          ))}

          {/* Empty folder message */}
          {cards.length === 0 && children.length === 0 && (
            <div className="text-center py-4 text-sm text-gray-400">
              空文件夹
            </div>
          )}
        </div>
      )}
    </>
  )
})

export type { FolderItemProps }
